import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const n="/assets/hdfcsky_1.Bb-WAhMU.PNG",s="/assets/hdfcsky_2.C63Iel3v.PNG",i="/assets/hdfcsky_3.Od9pQpIJ.PNG",p="/assets/hdfcsky_5.BhmoJ2TJ.PNG",c="/assets/hdfcsky_6.Cc-bFUCu.PNG",k=JSON.parse('{"title":"HDFC Sky","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/hdfc-sky.md","filePath":"connect-brokers/brokers/hdfc-sky.md"}'),d={name:"connect-brokers/brokers/hdfc-sky.md"};function l(g,e,h,f,u,m){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="hdfc-sky" tabindex="-1">HDFC Sky <a class="header-anchor" href="#hdfc-sky" aria-label="Permalink to &quot;HDFC Sky&quot;">​</a></h1><p>HDFC Sky (hdfcsky.com (<a href="https://www.hdfcsky.com/" target="_blank" rel="noreferrer">https://www.hdfcsky.com/</a>)) is the discount broking and investment platform from HDFC Securities, offering equity, F&amp;O, currency and commodity trading with a flat-fee brokerage model. Its Open API (developer.hdfcsky.com (<a href="https://developer.hdfcsky.com/" target="_blank" rel="noreferrer">https://developer.hdfcsky.com/</a>)) exposes REST and WebSocket endpoints for order placement, portfolio and funds management, and market data. Regulated by NSE, BSE and MCX, this API, used in the context of Tradeboard integration, enables automated trading strategies, real-time market data access, order management, and more.</p><p>The integration process involves logging in to the HDFC Sky Open API developer portal, creating a Trading API app, capturing the generated API Key and API Secret, and configuring them in Tradeboard&#39;s environmental variables.</p><h4 id="prerequisites" tabindex="-1"><strong>Prerequisites</strong> <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;**Prerequisites**&quot;">​</a></h4><p>Before proceeding with authentication, please make sure you have:</p><p>1) A valid HDFC Sky trading account (Client ID / registered Email / Mobile number)</p><p>2) Your registered mobile and email available to receive the login OTP</p><p>3) Registered your redirect URL in the developer portal (created inside the <strong>My Apps</strong> section of <a href="https://developer.hdfcsky.com/" target="_blank" rel="noreferrer">developer.hdfcsky.com</a>)</p><p>4) A static IP address ready (mandatory as per the latest SEBI Circular; the app form provides Primary and Secondary Static IP fields)</p><p>5) Your application credentials, <strong>API Key</strong> and <strong>API Secret</strong>, handy (generated after you click <strong>Create</strong> in the New App form)</p><h4 id="app-registration" tabindex="-1"><strong>App Registration</strong> <a class="header-anchor" href="#app-registration" aria-label="Permalink to &quot;**App Registration**&quot;">​</a></h4><p>Goto the HDFC Sky Open API developer portal at <a href="https://developer.hdfcsky.com/" target="_blank" rel="noreferrer">developer.hdfcsky.com</a> and log in with your HDFC Sky credentials.</p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p>Step 1: On the home page, click the <strong>Login</strong> button in the top-right corner.</p><p>Step 2: On the Login screen, enter your <strong>Client ID / Email ID / Mobile No.</strong> and click <strong>Proceed to HDFC SKY</strong>. (New users can click <strong>Sign Up</strong>.)</p><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p>Step 3: Enter the <strong>4 digit OTP</strong> sent to your registered mobile number and email ID to complete authentication.</p><p>Step 4: After login, a <strong>My Apps</strong> menu item appears in the top navigation bar. Click on <strong>My Apps</strong>.</p><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><p>Step 5: In the <strong>My Apps</strong> section, click the <strong>+ Create</strong> button to open the <strong>New App</strong> form.</p><p>Step 6: Fill in the form with the required details.</p><figure><img src="'+p+'" alt=""><figcaption></figcaption></figure><ul><li><strong>App Name</strong>: a name to identify your app, for example <code>tradeboard</code></li><li><strong>Redirect URL</strong>: <code>https://tradeboard.local/hdfcsky/callback</code></li><li><strong>Postback URL</strong>: an optional URL for order postback notifications (a dummy URL such as <code>https://google.com</code> can be used)</li><li><strong>Primary Static IP</strong>: your static IP, now mandatory as per the SEBI circular</li><li><strong>Secondary Static IP</strong>: an optional backup static IP address</li><li><strong>Description</strong>: a short description of your app, for example <code>tradeboard</code></li><li><strong>APIs in this app</strong>: keep <strong>Trading API</strong> selected (it enables placing orders and managing Stocks, Futures and Options)</li></ul><p>Step 7: Click <strong>Create</strong>.</p><blockquote><p>Note: Your created app will be <strong>deactivated by default</strong>. Go to the <strong>My Apps</strong> section and activate it before using the credentials.</p></blockquote><p>Step 8: In the <strong>My Apps</strong> list, confirm the app status shows <strong>Active</strong>. Reveal (eye icon) and <strong>Copy</strong> the <strong>API Key</strong> and <strong>API Secret</strong>.</p><figure><img src="'+c+`" alt=""><figcaption></figcaption></figure><p>Here is a sample of how the details would appear in a .env file for reference:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_api_key_here&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_api_secret_here&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;https://tradeboard.local/hdfcsky/callback&#39;</span></span></code></pre></div><p>Integrating Tradeboard with HDFC Sky&#39;s Open API opens up possibilities for automated trading strategies, providing a powerful tool for traders and developers to act on market opportunities efficiently. It&#39;s essential to follow best practices for API integration, including handling rate limits, managing credentials securely, and ensuring robust error handling and logging mechanisms are in place.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/hdfcsky/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,33)])])}const b=t(d,[["render",l]]);export{k as __pageData,b as default};
